DO $$ BEGIN CREATE TABLE public.apps (code varchar(32) PRIMARY KEY, name varchar(64) NOT NULL, description text NOT NULL, icon varchar(64) NOT NULL, identity_types text[] NOT NULL, sort integer NOT NULL DEFAULT 0 CHECK (sort >= 0), status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE public.features (app_code varchar(32) NOT NULL REFERENCES public.apps(code), code varchar(32) NOT NULL, name varchar(64) NOT NULL, actions text[] NOT NULL, status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (app_code, code)); CREATE TABLE public.menus (app_code varchar(32) NOT NULL REFERENCES public.apps(code), parent_key varchar(64), key varchar(64) NOT NULL, name varchar(64) NOT NULL, path varchar(255) NOT NULL, icon varchar(64), feature_code varchar(32) NOT NULL, client varchar(16) NOT NULL DEFAULT 'admin' CHECK (client IN ('admin','mobile')), sort integer NOT NULL DEFAULT 0 CHECK (sort >= 0), status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (app_code, key), UNIQUE (app_code, path), FOREIGN KEY (app_code, feature_code) REFERENCES public.features(app_code, code), FOREIGN KEY (app_code, parent_key) REFERENCES public.menus(app_code, key)); CREATE TABLE public.menu_overrides (app_code varchar(32) NOT NULL, menu_key varchar(64) NOT NULL, display_name varchar(64), sort integer CHECK (sort >= 0), icon varchar(64), hidden boolean, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (app_code, menu_key), FOREIGN KEY (app_code, menu_key) REFERENCES public.menus(app_code, key) ON DELETE CASCADE); END $$;
